import "server-only";
import fs from "node:fs";
import path from "node:path";
import { filesDir } from "./db";

export const maxFileBytes = () => (Number(process.env.MAX_FILE_MB) || 25) * 1024 * 1024;

/** Ids are generated by the server (base64url), so the path can never leave the files folder. */
export const filePath = (id: string) => path.join(filesDir(), id.replace(/[^A-Za-z0-9_-]/g, ""));

export function removeFiles(ids: string[]) {
  for (const id of ids) fs.rm(filePath(id), { force: true }, () => {});
}

/** Only these are shown inside the page. Everything else (HTML, SVG…) is downloaded, never run. */
export const INLINE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp", "image/avif"]);
